{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Safinamide, a basic amine-containing drug with an amide and fluorophenyl group, had absolute oral bioavailability of 95.0% (83.9-119.3%) after a 50 mg IR tablet in the fasted state in healthy subjects, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Darolutamide, a polar and moderately ionizable drug, showed 98.9% absolute oral bioavailability after a 300 mg oral solution in fasting healthy volunteers, indicating that polar/ionizable features do not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Linezolid is rapidly and completely absorbed with F approaching 100% after oral dosing in humans, demonstrating that a small molecule with polar amide and heterocyclic features can have essentially complete oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Aprepitant had 67% (62-73%) absolute oral bioavailability under fasting conditions, still well above the 20% threshold despite incomplete absorption and first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Cebranopadol, a basic amine-containing drug, had mean oral bioavailability of about 40% in fasted healthy subjects, showing that even substantial first-pass metabolism leaves F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Thalidomide, a small heterocyclic drug, had probably high absolute oral bioavailability (80-100%) at low doses in fasting healthy volunteers, supporting high F for a related heterocyclic query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to high oral bioavailability: multiple close-transfer analogues with ionizable or polar features show absolute F values of 40-100% in humans, all well above the 20% threshold. The physicochemical prior is mixed but not affirmative for low F, and no evidence supports F < 20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule.",
    "No specific data on intestinal permeability, efflux transport, or first-pass metabolism for the query.",
    "The query's very low neutral fraction at pH 7.4 is a theoretical absorption concern not reflected in the high-F analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

